var MSFAM = 'Georgia, "Times New Roman", serif';

var MS_PEAKS = [
  { mz: 25, a: 6, n: 'C₂H⁺' },
  { mz: 26, a: 28, n: 'C₂H₂⁺•' },
  { mz: 27, a: 75, n: 'C₂H₃⁺' },
  { mz: 28, a: 91, n: 'C₂H₄⁺•' },
  { mz: 29, a: 85, n: 'C₂H₅⁺ (loss of Cl)' },
  { mz: 30, a: 1.6, n: '' },
  { mz: 31, a: 0.8, n: '' },
  { mz: 35, a: 4.2, n: '³⁵Cl⁺' },
  { mz: 36, a: 4.6, n: 'H³⁵Cl⁺•' },
  { mz: 37, a: 2.4, n: '³⁷Cl⁺' },
  { mz: 38, a: 1.0, n: '' },
  { mz: 47, a: 3.0, n: '' },
  { mz: 48, a: 5.0, n: 'CH³⁵Cl⁺' },
  { mz: 49, a: 25, n: 'CH₂³⁵Cl⁺' },
  { mz: 51, a: 8, n: 'CH₂³⁷Cl⁺ (the 49/51 pair)' },
  { mz: 61, a: 1.0, n: '' },
  { mz: 62, a: 6, n: '' },
  { mz: 63, a: 4, n: 'C₂H₄³⁵Cl⁺' },
  { mz: 64, a: 100, n: 'M⁺• = C₂H₅³⁵Cl (base peak)' },
  { mz: 65, a: 4, n: '' },
  { mz: 66, a: 30, n: 'M+2 = C₂H₅³⁷Cl' },
  { mz: 67, a: 1.5, n: '' }
];

var msState = { assignments: false, selected: false, hover: -1, step: 0 };

var MS_CALLOUTS = [
