    narration: 'The tall line at m/z 64 (M) is bracketed with the line at m/z 66 (M+2). Their heights stand in a roughly 3:1 ratio — exactly the natural ³⁵Cl : ³⁷Cl abundance — which is why MW is quoted as 64.5 while the spectrum shows a 64 peak.',
    state: { assignments: true, selected: true }
  }
];

/* ── canvas ───────────────────────────────────────────────────────────── */
var msCanvas = document.createElement('canvas');
msCanvas.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(msCanvas);
var msCtx2d = msCanvas.getContext('2d');

function msFsFor(chart) {
  var s = Math.min(chart.width || 600, chart.height || 400);
  return Math.max(8, Math.min(14, s * 0.031));
}

function msColor(i) {
  var mz = MS_PEAKS[i].mz;
  var pair = (mz === 64 || mz === 66);
  if (msState.selected) {
    if (pair) return '#d6007e';
    return (msState.hover === i) ? '#8f8f8f' : '#cdcdcd';
  }
  if (msState.hover >= 0) {
    return (msState.hover === i) ? '#d6007e' : '#bcbcbc';
  }
  return '#000000';
}

/* ── rich text helpers (sub / super scripts, italics, halo) ───────────── */
function msPartFont(p, fs, italic) {
  var size = (p.sub || p.sup) ? fs * 0.7 : fs;
  var it = (p.i || italic) ? 'italic ' : '';
  return it + (Math.round(size * 10) / 10) + 'px ' + MSFAM;
}
function msRichWidth(c, parts, fs, italic) {
  var w = 0;
  for (var i = 0; i < parts.length; i++) { c.font = msPartFont(parts[i], fs, italic); w += c.measureText(parts[i].t).width; }
  return w;
}
function msDrawRich(c, parts, x, y, fs, align, color, halo, italic) {
  var w = msRichWidth(c, parts, fs, italic);
  var cx = (align === 'center') ? x - w / 2 : (align === 'right') ? x - w : x;
  c.textAlign = 'left'; c.textBaseline = 'alphabetic';
  for (var i = 0; i < parts.length; i++) {
    var p = parts[i];
    c.font = msPartFont(p, fs, italic);
    var dy = p.sub ? fs * 0.25 : (p.sup ? -fs * 0.36 : 0);
    if (halo) {
      c.lineWidth = Math.max(2, fs * 0.34);
      c.lineJoin = 'round';
      c.strokeStyle = 'rgba(255,255,255,0.94)';
      c.strokeText(p.t, cx, y + dy);
    }
    c.fillStyle = color;
    c.fillText(p.t, cx, y + dy);
    cx += c.measureText(p.t).width;
  }
  return w;
}

/* ── background: painted BEFORE the scales so ticks/labels survive ────── */
var msBackground = {
  id: 'msBackground',
  beforeDraw: function (chart) {
    var c = chart.ctx, a = chart.chartArea;
    c.save();
    c.fillStyle = '#ffffff';
    c.fillRect(0, 0, chart.width, chart.height);
    if (a) {
      var g = c.createLinearGradient(0, a.top, 0, a.bottom);
      g.addColorStop(0, '#e7e1d6');
      g.addColorStop(0.55, '#f4f1ec');
      g.addColorStop(1, '#fdfdfc');
      c.fillStyle = g;
      c.fillRect(a.left, a.top, a.width, a.height);
    }
    c.restore();
  }
};

/* ── annotation layer: drawn AFTER everything else ────────────────────── */
var msAnnotations = {
  id: 'msAnnotations',
  afterDraw: function (chart) {
    var c = chart.ctx, a = chart.chartArea;
    if (!a) return;
    var X = function (v) { return chart.scales.x.getPixelForValue(v); };
    var Y = function (v) { return chart.scales.y.getPixelForValue(v); };
    var fs = msFsFor(chart);
    c.save();

    /* thin black frame around the plot field */
    c.strokeStyle = '#000';
    c.lineWidth = 1;
    c.strokeRect(Math.round(a.left) + 0.5, Math.round(a.top) + 0.5,
      Math.round(a.width) - 1, Math.round(a.height) - 1);

    /* sample caption */
    var capFs = fs * 1.05;
    msDrawRich(c, [{ t: 'CH' }, { t: '3', sub: 1 }, { t: 'CH' }, { t: '2', sub: 1 }, { t: 'Cl' }],
      X(40), Y(87), capFs, 'center', '#111', true, false);
    msDrawRich(c, [{ t: 'MW = 64.5' }], X(40), Y(79), capFs, 'center', '#111', true, false);

    /* M (64) and M + 2 labels (italic serif, upper / mid right) */
    var labFs = fs * 1.05;
    var accent = '#d6007e';
    msDrawRich(c, [{ t: 'M', i: 1 }, { t: ' (64)' }],
      a.right - 4, msState.selected ? Y(95) : Y(104), labFs, 'right',
      msState.selected ? accent : '#111', true, false);
    msDrawRich(c, [{ t: 'M', i: 1 }, { t: ' + 2' }],
      a.right - 4, Y(33.5), labFs, 'right',
      msState.selected ? accent : '#111', true, false);

    /* m/z axis label with magenta arrow, placed below the tick labels */
    var axFs = fs * 1.05;
    c.font = 'italic ' + axFs + 'px ' + MSFAM;
    var tw = c.measureText('m/z').width;
    var arrowLen = axFs * 2.8, gap = axFs * 0.6;
    var total = tw + gap + arrowLen;
    var startX = (a.left + a.right) / 2 - total / 2;
    var xScaleBottom = (chart.scales.x && chart.scales.x.bottom) ? chart.scales.x.bottom : a.bottom + fs * 1.6;
    var yLab = Math.min(chart.height - 3, xScaleBottom + axFs * 1.35);
    c.textAlign = 'left'; c.textBaseline = 'alphabetic';
    c.fillStyle = '#111';
    c.fillText('m/z', startX, yLab);
    var ax0 = startX + tw + gap, ax1 = ax0 + arrowLen, ay = yLab - axFs * 0.3;
    c.strokeStyle = '#e5007e';
    c.lineWidth = Math.max(1.6, axFs * 0.2);
    c.beginPath(); c.moveTo(ax0, ay); c.lineTo(ax1 - axFs * 0.45, ay); c.stroke();
    c.beginPath();
    c.moveTo(ax1, ay);
    c.lineTo(ax1 - axFs * 0.7, ay - axFs * 0.36);
    c.lineTo(ax1 - axFs * 0.7, ay + axFs * 0.36);
    c.closePath();
    c.fillStyle = '#e5007e';
    c.fill();

    /* fragment assignment callouts (hidden when the panel is very small) */
    if (msState.assignments && a.width > 200) {
      var sFs = fs * 0.85;
      for (var k = 0; k < MS_CALLOUTS.length; k++) {
        var co = MS_CALLOUTS[k];
        var w = msRichWidth(c, co.parts, sFs, false);
        var lx = X(co.x), ly = Y(co.y);
        lx = Math.max(a.left + w / 2 + 4, Math.min(a.right - w / 2 - 4, lx));
        var tx = X(co.tx), ty = Y(co.ty);
        var dx = tx - lx, dy = ty - ly, d = Math.sqrt(dx * dx + dy * dy) || 1;
        var off = Math.min(d - 3, w / 2 + sFs * 0.7);
        c.strokeStyle = '#8a8a8a';
        c.lineWidth = Math.max(0.8, fs * 0.075);
        c.beginPath();
        c.moveTo(lx + dx / d * off, ly + dy / d * off);
        c.lineTo(tx, ty);
        c.stroke();
        c.beginPath();
        c.arc(tx, ty, Math.max(1.2, fs * 0.14), 0, Math.PI * 2);
        c.fillStyle = '#8a8a8a';
        c.fill();
        msDrawRich(c, co.parts, lx, ly + sFs * 0.35, sFs, 'center', '#333', true, false);
      }
    }

    /* isotope bracket when the pair is selected */
    if (msState.selected) {
      var yB = Y(104.5);
      var x64 = X(64), x66 = X(66);
      c.strokeStyle = accent;
      c.lineWidth = Math.max(1.2, fs * 0.13);
      c.setLineDash([3, 3]);
      c.beginPath(); c.moveTo(x64, Y(100.5)); c.lineTo(x64, yB); c.stroke();
      c.beginPath(); c.moveTo(x66, Y(30.5)); c.lineTo(x66, yB); c.stroke();
      c.setLineDash([]);
      c.beginPath(); c.moveTo(x64, yB); c.lineTo(x66, yB); c.stroke();
      var rFs = fs * 0.92;
      var lead = x64 - fs * 0.6;
      c.beginPath(); c.moveTo(lead, yB); c.lineTo(lead - fs * 0.8, yB); c.stroke();
      msDrawRich(c, [
        { t: '100 : 30  ≈  3 : 1   (' },
        { t: '35', sup: 1 }, { t: 'Cl : ' }, { t: '37', sup: 1 }, { t: 'Cl)' }
      ], lead - fs * 1.1, yB + rFs * 0.35, rFs, 'right', accent, true, false);
    }

    c.restore();
  }
};

/* ── chart ────────────────────────────────────────────────────────────── */
var msChart = new Chart(msCtx2d, {
  type: 'bar',
  data: {
    datasets: [{
      data: MS_PEAKS.map(function (p) { return { x: p.mz, y: p.a }; }),
      backgroundColor: function (c) { return msColor(c.dataIndex); },
      borderWidth: 0,
      barThickness: 2,
      grouped: false
    }]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: { duration: 0 },
    layout: { padding: { top: 8, right: 10, bottom: 26, left: 2 } },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: {
        type: 'linear',
        min: 10,
        max: 70,
        offset: false,
        grid: { display: false, drawTicks: true, tickColor: '#000', tickLength: 5 },
        border: { color: '#000', width: 1 },
        ticks: {
          stepSize: 5,
          autoSkip: true,
          maxRotation: 0,
          color: '#000',
          padding: 3,
          font: { size: 12, family: MSFAM }
        }
      },
      y: {
        min: 0,
        max: 110,
        grid: { display: false, drawTicks: true, tickColor: '#000', tickLength: 5 },
        border: { color: '#000', width: 1 },
        afterBuildTicks: function (scale) {
          scale.ticks = [0, 20, 40, 60, 80, 100].map(function (v) { return { value: v }; });
        },
        ticks: { color: '#000', padding: 4, font: { size: 12, family: MSFAM } },
        title: {
          display: true,
          text: 'Relative abundance (%)',
          color: '#000',
          font: { size: 13, family: MSFAM }
        }
      }
    }
  },
  plugins: [msBackground, msAnnotations]
});

window.__markRendered();

function msResize() {
  var fs = msFsFor(msChart);
  var small = Math.min(msChart.width || 600, msChart.height || 400) < 260;
  msChart.options.scales.x.ticks.font.size = fs;
  msChart.options.scales.y.ticks.font.size = fs;
  msChart.options.scales.y.title.display = !small;
  msChart.options.scales.y.title.font.size = fs * 1.05;
  msChart.options.layout.padding.bottom = Math.round(fs * 2.0);
  msChart.options.layout.padding.top = Math.round(fs * 0.6);
  msChart.data.datasets[0].barThickness =
    Math.max(1.1, Math.min(3.2, (msChart.width || 600) * 0.0038));
  msChart.update('none');
}
msResize();
document.addEventListener('fig-resize', function () { setTimeout(msResize, 0); });

/* ── hover / click interaction ────────────────────────────────────────── */
function msPick(e) {
  var a = msChart.chartArea;
  if (!a) return -1;
  var px = e.offsetX, py = e.offsetY;
  if (px < a.left || px > a.right || py < a.top - 4 || py > a.bottom + 4) return -1;
  var best = -1, bd = 1e9;
  for (var i = 0; i < MS_PEAKS.length; i++) {
    var d = Math.abs(msChart.scales.x.getPixelForValue(MS_PEAKS[i].mz) - px);
    if (d < bd) { bd = d; best = i; }
  }
  var tol = Math.max(5, a.width * 0.011);
  return (bd <= tol) ? best : -1;
}

msCanvas.addEventListener('mousemove', function (e) {
  var i = msPick(e);
  if (i !== msState.hover) {
    msState.hover = i;
    msChart.update('none');
  }
  if (i >= 0) {
    var p = MS_PEAKS[i];
    msCanvas.style.cursor = 'pointer';
    showTooltip('m/z = ' + p.mz + '  ·  abundance = ' + p.a + '%' + (p.n ? '  ·  ' + p.n : ''), e);
  } else {
    msCanvas.style.cursor = 'default';
    hideTooltip();
  }
});

msCanvas.addEventListener('mouseleave', function () {
  if (msState.hover !== -1) { msState.hover = -1; msChart.update('none'); }
  hideTooltip();
  msCanvas.style.cursor = 'default';
});

msCanvas.addEventListener('click', function (e) {
  var i = msPick(e);
  if (i >= 0 && (MS_PEAKS[i].mz === 64 || MS_PEAKS[i].mz === 66)) {
    msState.selected = true;
    msChart.update('none');
    showPopup('The M / M+2 isotope pair',
      'The line at m/z 64 is the molecular ion C₂H₅³⁵Cl⁺• and the line at m/z 66 is the very same molecule built with ³⁷Cl instead. Chlorine occurs naturally as about 75.8% ³⁵Cl and 24.2% ³⁷Cl, so the two peaks appear two mass units apart with heights close to 100 : 30, i.e. roughly 3 : 1. The mass spectrometer weighs individual isotopic molecules, whereas the tabulated MW of 64.5 is only the weighted average of the two.');
  } else if (msState.selected) {
    msState.selected = false;
    msChart.update('none');
    hidePopup();
  }
});

/* ── controls ─────────────────────────────────────────────────────────── */
function toggle_showAssignments(on) {
  msState.assignments = !!on;
  msChart.update('none');
}
function trigger_highlightPair() {
  msState.selected = true;
  msChart.update('none');
}
function trigger_clearSelection() {
  msState.selected = false;
  msChart.update('none');
  hidePopup();
}

/* ── demo step player ─────────────────────────────────────────────────── */
function setStep(i) {
  msState.step = Math.max(0, Math.min(MS_STEPS.length - 1, i));
  var s = MS_STEPS[msState.step];
  var cb = document.getElementById('showAssignmentsInput');
  cb.checked = !!s.state.assignments;
  toggle_showAssignments(cb.checked);
  msState.selected = !!s.state.selected;
  msChart.update('none');
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent =
    'Step ' + (msState.step + 1) + '/' + MS_STEPS.length + ' — ' + s.title;
}
function nextStep() { setStep(msState.step + 1); }
function prevStep() { setStep(msState.step - 1); }

setStep(0);
// @FIGURE_CODE_END

